using Microsoft.Xna.Framework;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace StarlightSyndicateDemo;
public static class AgentTests38
{
 static int checks;static void Check(bool value,string label){if(!value)throw new Exception("AGENTS FAIL: "+label);Console.WriteLine("PASS: "+label);checks++;}
 static DemoWorld World(){var w=new DemoWorld();w.NewGame(0);return w;}
 public static void Run()
 {
  SkillCatalog.VerificationAllV=false;string? previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"agents38-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
  try{
   var w=World();var a=AgentCatalog38.Agents.First(a=>a.Station=="aster"&&a.Level==1&&a.Division==AgentDivision38.Distribution);var l4=AgentCatalog38.Agents.First(a=>a.Station=="aster"&&a.Level==4&&a.Division==AgentDivision38.Security);
   Check(AgentCatalog38.Agents.Length==108,"every station has all 12 level/division combinations");Check(AgentCatalog38.Missions.Count>=600,"report catalogue loaded");Check(AgentCatalog38.Missions.Values.Count(m=>m.Coverage!="Indexed")>=500,"playable adaptation catalogue loaded");
   foreach(var d in Enum.GetValues<AgentDivision38>())foreach(int l in Enumerable.Range(1,4))Check(AgentCatalog38.Missions.Values.Any(m=>m.Division==d&&m.Level==l&&m.Coverage!="Indexed"),$"{d} L{l} has playable offers");
   w.AgentsState.Standings[a.Faction]=-10;w.AgentsState.Standings[a.Corporation]=-10;Check(w.CanUseAgent38(a),"L1 available despite hostile faction and corporation");Check(!w.CanUseAgent38(l4),"hostile faction blocks L4");w.AgentsState.Standings[a.Faction]=5;w.AgentsState.Standings[a.Corporation]=0;Check(w.CanUseAgent38(l4),"faction standing unlocks L4");w.AgentsState.Standings[l4.Id]=-2;Check(!w.CanUseAgent38(l4),"-2 agent relationship vetoes L4");w.AgentsState.Standings[l4.Id]=0;
   w.AgentsState.Standings["math"]=1;w.ChangeStanding38("math",.05,"gain");Check(Math.Abs(w.RawStanding38("math")-1.45)<.0001,"diminishing gain uses distance to +10");w.AgentsState.Standings["math"]=1;w.ChangeStanding38("math",-.05,"loss");Check(Math.Abs(w.RawStanding38("math")-.45)<.0001,"loss uses distance to -10");
   w.Player.SkillLevels[SkillCatalog.Id("Diplomacy")]=5;w.AgentsState.Standings["math"]=-5;Check(Math.Abs(w.EffectiveStanding38("math")+2)<.001,"Diplomacy effective negative standing");Check(w.EffectiveStanding38("unseen")==0,"social skills do not create an unseen relationship");w.Player.SkillLevels.Clear();
   DateTime now=w.Now;Check(w.RequestMission38(a.Id,now)=="","agent produces mission offer");var m=w.AgentsState.Missions.Last();Check(w.RequestMission38(a.Id,now)!="","one outstanding mission per agent");Check(w.AcceptMission38(m.Id,now)=="","offer accepts");Check(m.Hangars[a.Station]==m.Spec.Volume&&m.Cargo==0,"courier freight starts in pickup hangar");Check(w.CompleteMission38(m.Id,now)!="","cannot turn in courier at pickup");
   w.Player.CargoMax=100000;Check(w.TransferMissionCargo38(m.Id,true,m.Spec.Volume)=="","load consumes pickup stack");Check(w.MissionCargoVolume38==m.Spec.Volume&&w.CargoUsed>=m.Spec.Volume,"mission cargo counts against cargo capacity");Check(w.TransferMissionCargo38(m.Id,true,1)!="","cannot duplicate loaded cargo");w.SystemId=m.Destination;decimal before=w.Balance;Check(w.CompleteMission38(m.Id,now.AddMinutes(5))=="","remote agent turn-in at destination with ship cargo");Check(w.Balance==before+m.Reward+m.Bonus,"reward and timely bonus credited once");Check(w.CompleteMission38(m.Id,now)!="","duplicate completion rejected");Check(w.MissionCargoVolume38==0,"turn-in consumes mission freight");Check(w.AgentsState.Loyalty[a.Corporation]==m.LP,"LP credited to issuer corporation");Check(w.RawStanding38(a.Corporation)>0,"corporation standing increases");Check(w.RawStanding38(a.Faction)==5,"normal mission gives no faction standing");
   w.SystemId=a.Station;Check(w.RequestMission38(a.Id,now)=="","new mission after completion");var declined=w.AgentsState.Missions.Last();double corp=w.RawStanding38(a.Corporation);Check(w.DeclineMission38(declined.Id,now)==""&&w.RawStanding38(a.Corporation)==corp,"first decline is free");w.RequestMission38(a.Id,now.AddMinutes(1));declined=w.AgentsState.Missions.Last();Check(w.DeclineMission38(declined.Id,now.AddMinutes(1))==""&&w.RawStanding38(a.Corporation)<corp,"second decline within four hours penalized");
   var miner=AgentCatalog38.Agents.First(a=>a.Station=="aster"&&a.Level==1&&a.Division==AgentDivision38.Mining);w.RequestMission38(miner.Id,now);var mm=w.AgentsState.Missions.Last();w.AcceptMission38(mm.Id,now);w.Undock();Check(w.MissionWarpTarget38(mm.WarpId,out var pos),"accepted mining site provides warp solution");Check(w.BeginWarp(mm.WarpId),"mission begins real warp transit");w.EnterGrid(mm.WarpId,false);var rock=w.Targets.First(t=>t.Kind==TargetKind.Asteroid);float cargo=w.MissionCargoVolume38;Check(w.HarvestMission38(rock,50)==50&&mm.Harvested==50&&w.MissionCargoVolume38==cargo+50,"mission asteroid deposits unique contract resource");Check(w.Player.Ore==0,"mission resource does not create commodity ore");w.Screen=ViewMode.Station;w.Grid="station";Check(w.CompleteMission38(mm.Id,now)!="","partial harvest cannot complete");w.TransferMissionCargo38(mm.Id,false,mm.Cargo);Check(mm.Hangars["aster"]==50,"mission material unloads to local hangar");
   w.AgentsState.StorylineCounts[a.Faction+"/1"]=15;w.RequestMission38(a.Id,now.AddHours(5));var storyTrigger=w.AgentsState.Missions.Last();w.AcceptMission38(storyTrigger.Id,now.AddHours(5));storyTrigger.Cargo=storyTrigger.Spec.Volume;storyTrigger.Hangars.Clear();w.SystemId=storyTrigger.Destination;Check(w.CompleteMission38(storyTrigger.Id,now.AddHours(5))==""&&w.AgentsState.Missions.Any(m=>m.Storyline),"16 missions counted by faction and level create important offer");
   w.Screen=ViewMode.Station;w.Grid="station";w.Save();var load=new DemoWorld();Check(load.Load(),"save loads with agent state");Check(load.AgentsState.Missions.Count==w.AgentsState.Missions.Count&&load.AgentsState.History.Count==w.AgentsState.History.Count,"missions and standing transaction history survive save/load");
   var expired=load.AgentsState.Missions.First(m=>m.State=="Accepted");load.UpdateMissions38(expired.Expires.AddSeconds(1));Check(expired.State=="Expired"&&expired.Cargo==0&&expired.Hangars.Count==0,"accepted deadline fails and removes contract cargo");
   var save=JsonNode.Parse(File.ReadAllText(DemoWorld.SavePath))!;save.AsObject().Remove("AgentState");File.WriteAllText(DemoWorld.SavePath,save.ToJsonString());var legacy=new DemoWorld();Check(legacy.Load()&&legacy.AgentsState.Missions.Count==0,"Pass 37 saves migrate without invented missions");
   var sec=World();sec.Player.CargoMax=100000;var agent=AgentCatalog38.Agents.First(a=>a.Station=="aster"&&a.Level==1&&a.Division==AgentDivision38.Security);sec.RequestMission38(agent.Id);var combat=sec.AgentsState.Missions.Last();sec.AcceptMission38(combat.Id);sec.Undock();sec.EnterGrid(combat.WarpId,false);Check(sec.Targets.Any(t=>t.Kind==TargetKind.Raider),"security mission creates live hostiles");int safety=0;while(!combat.ObjectiveDone&&safety++<100){foreach(var enemy in sec.Targets.Where(t=>t.Kind==TargetKind.Raider&&t.Alive).ToArray())sec.DamageMissionAudit38(enemy);}Check(combat.ObjectiveDone,"combat kills advance waves and complete objective");
   var fleet=World();fleet.AgentsState.Standings[fleet.StationCorporation]=6.67;Check(fleet.IndustryStanding==6.67,"reprocessing uses station corporation effective standing");Check(fleet.StationBrokerRate38<.03m,"broker fees respond to corporation standing");
   var hostileMining=World();var miningAgent=AgentCatalog38.Agents.First(a=>a.Station=="aster"&&a.Level==3&&a.Division==AgentDivision38.Mining);hostileMining.AgentsState.Standings[miningAgent.Corporation]=5;var miningPool=AgentCatalog38.Missions.Values.Where(d=>d.Level==3&&d.Division==AgentDivision38.Mining&&d.Coverage!="Indexed"&&d.Part==1).OrderBy(d=>d.Id).ToArray();hostileMining.AgentsState.OfferSequence[miningAgent.Id]=Array.FindIndex(miningPool,d=>d.Hostiles);Check(hostileMining.RequestMission38(miningAgent.Id)=="","hostile mining mission offered by eligible L3 agent");var hm=hostileMining.AgentsState.Missions.Last();hostileMining.AcceptMission38(hm.Id);hostileMining.Undock();hostileMining.EnterGrid(hm.WarpId,false);foreach(var enemy in hostileMining.Targets.Where(t=>t.Kind==TargetKind.Raider).ToArray())hostileMining.DamageMissionAudit38(enemy);hostileMining.EnterGrid(hm.WarpId,false);Check(hostileMining.Targets.Any(t=>t.Kind==TargetKind.Asteroid&&t.Ore==hm.Spec.Volume),"killing mining hostiles does not remove required asteroids");Check(!hostileMining.Targets.Any(t=>t.Kind==TargetKind.Raider&&t.Alive),"defeated mining hostiles do not respawn on return");
   hostileMining.Save();var missionLoad=new DemoWorld();Check(missionLoad.Load()&&missionLoad.Grid==hm.WarpId&&missionLoad.Targets.Any(t=>t.Kind==TargetKind.Asteroid&&t.Id==hm.WarpId+":resource"),"mission-site targets survive in-space save/load without restoring an unrelated solar grid");
   var navy=World();navy.AgentsState.Standings[navy.StationFaction]=-5;navy.Undock();navy.UpdateStandingNavy38();Check(navy.Targets.Count(t=>t.Id.StartsWith("navy:"))==2,"hostile high-security faction deploys navy");navy.UpdateStandingNavy38();Check(navy.Targets.Count(t=>t.Id.StartsWith("navy:"))==2,"navy response is not duplicated each frame");navy.FactionKill38("Boreal Federation");double loss=navy.RawStanding38("Boreal Federation");navy.FactionKill38("Boreal Federation");Check(navy.RawStanding38("Boreal Federation")==loss,"faction ship-kill loss uses ten-minute system tick");navy.Player.SkillLevels[SkillCatalog.Id("Criminal Connections")]=5;navy.AgentsState.Standings["Pale Orchard"]=0;Check(navy.EffectiveStanding38("Pale Orchard")==2,"Criminal Connections applies to pirate factions");
   Console.WriteLine($"Agent Pass 38: {checks} checks passed. {AgentCatalog38.Missions.Count} indexed catalogue entries.");
  }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);if(Directory.Exists(dir))Directory.Delete(dir,true);}
 }
}

public sealed partial class DemoWorld { internal void DamageMissionAudit38(SpaceTarget t)=>ApplyPacket(t,DamagePacket.Single(10000000,DamageType.EM)); }
